import{_ as n,o as t,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Space anlegen","description":"Einen Space erstellen, benennen und sinnvoll zuschneiden.","frontmatter":{"title":"Space anlegen","description":"Einen Space erstellen, benennen und sinnvoll zuschneiden."},"headers":[],"relativePath":"spaces/space-anlegen.md","filePath":"spaces/space-anlegen.md","lastUpdated":1786087067000}'),r={name:"spaces/space-anlegen.md"};function s(l,e,o,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="space-anlegen" tabindex="-1">Space anlegen <a class="header-anchor" href="#space-anlegen" aria-label="Permalink to &quot;Space anlegen&quot;">​</a></h1><p>Ein <strong>Space</strong> ist die oberste Organisationseinheit. Er enthält Grids, Seiten und Flows — und er ist die Einheit, an der Zugriffsrechte, Tarif und Sitzplätze hängen.</p><h2 id="space-erstellen" tabindex="-1">Space erstellen <a class="header-anchor" href="#space-erstellen" aria-label="Permalink to &quot;Space erstellen&quot;">​</a></h2><ol><li>Öffnen Sie die Übersicht über <strong>Alle Spaces</strong>.</li><li>Klicken Sie auf <strong>Neuen Space erstellen</strong>.</li><li>Vergeben Sie einen Namen.</li></ol><p>Der Dialog heißt <em>Einen Space erstellen</em> mit dem Hinweis <em>Lassen Sie uns mit einem Namen für Ihren Space beginnen</em>.</p><p>Haben Sie noch keinen Space, steht dort stattdessen <em>Erstelle deinen ersten Space</em>.</p><p>Direkt danach bietet ApptiveGrid an, das erste Grid anzulegen: <em>Grid erstellen</em> — <em>Wählen Sie nun einen Namen für Ihr erstes Grid</em>.</p><h2 id="wie-sie-spaces-zuschneiden" tabindex="-1">Wie Sie Spaces zuschneiden <a class="header-anchor" href="#wie-sie-spaces-zuschneiden" aria-label="Permalink to &quot;Wie Sie Spaces zuschneiden&quot;">​</a></h2><p>Das ist die wichtigste Entscheidung, und sie lässt sich später nur mit Aufwand ändern.</p><div class="warning custom-block"><p class="custom-block-title">Ein Space ist die Grenze für Zugriff und Kosten</p><p>Wer Zugriff auf einen Space hat, sieht <strong>alles</strong> darin — im Rahmen seiner <a href="/zusammenarbeit/rollen">Rolle</a>. Es gibt keine Berechtigung je Grid.</p><p>Auch der Tarif und die <a href="/zusammenarbeit/sitzplaetze">Sitzplätze</a> gelten je Space, nicht je Konto.</p></div><p>Daraus folgt die Faustregel:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Empfehlung</th></tr></thead><tbody><tr><td>Ein Team arbeitet an mehreren Themen</td><td><strong>Ein</strong> Space, mehrere Grids</td></tr><tr><td>Verschiedene Personenkreise, getrennte Daten</td><td><strong>Mehrere</strong> Spaces</td></tr><tr><td>Kundendaten, die Kunden nicht gegenseitig sehen dürfen</td><td><strong>Mehrere</strong> Spaces, oder ein <a href="/seiten/portal-veroeffentlichen">Portal</a> statt Einladung</td></tr><tr><td>Personalbezogene Daten neben allgemeinen</td><td><strong>Eigener</strong> Space</td></tr><tr><td>Test- und Spielwiese</td><td><strong>Eigener</strong> Space</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Nicht vorschnell aufteilen</p><p>Verknüpfungen zwischen Grids funktionieren nur <strong>innerhalb</strong> eines Space. Was fachlich zusammengehört, sollte deshalb zusammen liegen — sonst können Sie später keine Verknüpfungen bauen.</p><p>Teilen Sie also nach <em>Zugriff</em>, nicht nach Thema.</p></div><h2 id="kategorien" tabindex="-1">Kategorien <a class="header-anchor" href="#kategorien" aria-label="Permalink to &quot;Kategorien&quot;">​</a></h2><p>Spaces lassen sich einer <strong>Kategorie</strong> zuordnen. In der Übersicht bündelt <strong>Nach Kategorie gruppieren</strong> sie entsprechend; Spaces ohne Zuordnung erscheinen unter <em>Keine Kategorie</em>.</p><div class="tip custom-block"><p class="custom-block-title">Ab etwa zehn Spaces</p><p>Bei wenigen Spaces genügt die Suche (<em>Space suchen…</em>). Wächst die Liste, sind Kategorien wie „Kunden&quot;, „Intern&quot;, „Archiv&quot; das einfachste Ordnungsmittel.</p></div><h2 id="mit-einer-vorlage-starten" tabindex="-1">Mit einer Vorlage starten <a class="header-anchor" href="#mit-einer-vorlage-starten" aria-label="Permalink to &quot;Mit einer Vorlage starten&quot;">​</a></h2><p>Unter der Space-Liste steht <em>Oder starten Sie mit einem Template</em>. Eine Vorlage legt einen Space mit fertigen Grids, Ansichten und teils Formularen und Flows an.</p><div class="warning custom-block"><p class="custom-block-title">Manche Vorlagen brauchen einen höheren Tarif</p><blockquote><p><em>Für dieses Template benötigen Sie mindestens einen „{plan}&quot; Plan</em></p></blockquote><p>Nach Ablauf der Testphase kann eine Vorlage unbenutzbar werden: <em>Sie haben die Testphase für dieses Template abgeschlossen. Um dieses Template weiterhin nutzen zu können, upgraden Sie bitte auf einen höheren Plan.</em></p></div><p>→ <a href="/erste-schritte/vorlagen">Mit einer Vorlage starten</a></p><h2 id="space-umbenennen" tabindex="-1">Space umbenennen <a class="header-anchor" href="#space-umbenennen" aria-label="Permalink to &quot;Space umbenennen&quot;">​</a></h2><p>Über <strong>Space umbenennen</strong> im Space-Menü. Der Dialog fragt: <em>Geben Sie einen neuen Namen für dieses Space ein.</em></p><div class="tip custom-block"><p class="custom-block-title">Umbenennen ist unkritisch</p><p>Grids, Ansichten, Formulare, Flows und geteilte Links bleiben unverändert funktionsfähig — intern wird nicht über den Namen verwiesen.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/spaces/symbol-und-farbe">Symbol, Farbe und Kategorie</a></li><li><a href="/spaces/navigation">Navigation einrichten</a></li><li><a href="/spaces/einstellungen">Space-Einstellungen</a></li><li><a href="/zusammenarbeit/personen-einladen">Personen einladen</a></li></ul>',25)])])}const g=n(r,[["render",s]]);export{u as __pageData,g as default};
